-- Tamagotui Cloud Sync / Snapshot / Integrations Schema Migration

CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ==========================================
-- sync_api service tables
-- ==========================================

CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email TEXT NOT NULL,
    username TEXT NOT NULL,
    password_hash TEXT,
    avatar_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE UNIQUE INDEX idx_users_email ON users (email);
CREATE UNIQUE INDEX idx_users_username ON users (username);

CREATE TABLE devices (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_name TEXT,
    hostname TEXT,
    os TEXT,
    last_synced_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_devices_user_id ON devices (user_id);

CREATE TABLE pets (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id UUID REFERENCES devices(id) ON DELETE SET NULL,
    name TEXT,
    species TEXT NOT NULL DEFAULT 'egg',
    growth_stage TEXT NOT NULL DEFAULT 'egg',
    xp INTEGER NOT NULL DEFAULT 0,
    mood TEXT NOT NULL DEFAULT 'neutral',
    health_state TEXT NOT NULL DEFAULT 'healthy',
    current_streak_days INTEGER NOT NULL DEFAULT 0,
    longest_streak_days INTEGER NOT NULL DEFAULT 0,
    last_activity_at TIMESTAMPTZ,
    hatched_at TIMESTAMPTZ,
    seed_hash TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_pets_user_id ON pets (user_id);
CREATE INDEX idx_pets_device_id ON pets (device_id);
CREATE INDEX idx_pets_seed_hash ON pets (seed_hash);

CREATE TABLE pet_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pet_id UUID NOT NULL REFERENCES pets(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    source TEXT,
    xp_awarded INTEGER NOT NULL DEFAULT 0,
    metadata JSONB,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_pet_events_pet_id ON pet_events (pet_id);
CREATE INDEX idx_pet_events_occurred_at ON pet_events (occurred_at);
CREATE INDEX idx_pet_events_event_type ON pet_events (event_type);

CREATE TABLE pet_pairings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pet_id_a UUID NOT NULL REFERENCES pets(id) ON DELETE CASCADE,
    pet_id_b UUID NOT NULL REFERENCES pets(id) ON DELETE CASCADE,
    shared_seed_hash TEXT NOT NULL,
    pr_reference TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_pet_pairings_pet_id_a ON pet_pairings (pet_id_a);
CREATE INDEX idx_pet_pairings_pet_id_b ON pet_pairings (pet_id_b);
CREATE INDEX idx_pet_pairings_shared_seed_hash ON pet_pairings (shared_seed_hash);

CREATE TABLE sync_tokens (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    device_id UUID REFERENCES devices(id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL,
    expires_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_sync_tokens_user_id ON sync_tokens (user_id);
CREATE UNIQUE INDEX idx_sync_tokens_token_hash ON sync_tokens (token_hash);

-- ==========================================
-- snapshot_service tables
-- ==========================================

CREATE TABLE snapshots (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    pet_id UUID NOT NULL REFERENCES pets(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    file_url TEXT NOT NULL,
    file_format TEXT NOT NULL DEFAULT 'png',
    growth_stage TEXT,
    xp_at_capture INTEGER,
    stats_snapshot JSONB,
    share_slug TEXT,
    is_public BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_snapshots_pet_id ON snapshots (pet_id);
CREATE INDEX idx_snapshots_user_id ON snapshots (user_id);
CREATE UNIQUE INDEX idx_snapshots_share_slug ON snapshots (share_slug);

CREATE TABLE snapshot_shares (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    snapshot_id UUID NOT NULL REFERENCES snapshots(id) ON DELETE CASCADE,
    platform TEXT,
    shared_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_snapshot_shares_snapshot_id ON snapshot_shares (snapshot_id);

-- ==========================================
-- integrations_poller tables
-- ==========================================

CREATE TABLE integration_connections (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    provider TEXT NOT NULL,
    external_account_id TEXT,
    access_token TEXT NOT NULL,
    refresh_token TEXT,
    token_expires_at TIMESTAMPTZ,
    scopes TEXT,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_integration_connections_user_id ON integration_connections (user_id);
CREATE INDEX idx_integration_connections_provider ON integration_connections (provider);

CREATE TABLE watched_repos (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    integration_connection_id UUID NOT NULL REFERENCES integration_connections(id) ON DELETE CASCADE,
    repo_full_name TEXT NOT NULL,
    external_repo_id TEXT,
    last_polled_at TIMESTAMPTZ,
    poll_cursor TEXT,
    is_active BOOLEAN NOT NULL DEFAULT true,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_watched_repos_connection_id ON watched_repos (integration_connection_id);
CREATE INDEX idx_watched_repos_repo_full_name ON watched_repos (repo_full_name);

CREATE TABLE polled_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    watched_repo_id UUID NOT NULL REFERENCES watched_repos(id) ON DELETE CASCADE,
    event_type TEXT NOT NULL,
    external_event_id TEXT NOT NULL,
    payload JSONB,
    occurred_at TIMESTAMPTZ NOT NULL,
    processed_at TIMESTAMPTZ,
    forwarded_to_pet_event_id UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX idx_polled_events_watched_repo_id ON polled_events (watched_repo_id);
CREATE UNIQUE INDEX idx_polled_events_external_event_id ON polled_events (external_event_id);
CREATE INDEX idx_polled_events_occurred_at ON polled_events (occurred_at);
CREATE INDEX idx_polled_events_processed_at ON polled_events (processed_at);
